const fs = require('fs');
const path = require('path');
const http = require('http');

// Read and parse .env.test file
const envFilePath = path.join(__dirname, '.env.test');
const envContent = fs.readFileSync(envFilePath, 'utf8');

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  line = line.trim();
  // Skip comments and empty lines
  if (!line || line.startsWith('#')) return;

  // Parse KEY=VALUE
  const [key, ...valueParts] = line.split('=');
  if (key && valueParts.length > 0) {
    envVars[key.trim()] = valueParts.join('=').trim();
  }
});

// Prepare the data to send
const postData = JSON.stringify(envVars, null, 2);

console.log('Environment variables to POST:');
console.log(postData);

// Prepare POST request options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

//Create and send the request
const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log(`\nResponse status: ${res.statusCode}`);
    console.log('Response body:', data);
  });
});

req.on('error', (error) => {
  console.error('Error making request:', error.message);
});

// Send the data
req.write(postData);
req.end();

console.log(`\nSending POST request to http://localhost:47301/api/doc-export`);

